INSERT INTO qms.clause_registry (id, standard, clause_no, clause_title, intent_paraphrase, annex_sl_mode, harmonization_key, doc_type, required_sources, sort_order) VALUES
  ('d0000001-0001-4000-8000-000000000001', 'ISO9001', '4.1', 'Understanding the organization and its context', 'Determine the external and internal issues relevant to the purpose and strategic direction of the organization that affect its ability to achieve the intended results of the QMS.', 'shared', '4.1', 'procedure', '["org_profile.industry","org_profile.productsServices","register.interested_parties"]', 10),
  ('d0000001-0001-4000-8000-000000000002', 'ISO9001', '4.2', 'Understanding the needs and expectations of interested parties', 'Identify the interested parties relevant to the QMS and determine their relevant requirements.', 'shared', '4.2', 'procedure', '["register.interested_parties"]', 20),
  ('d0000001-0001-4000-8000-000000000003', 'ISO9001', '4.3', 'Determining the scope of the QMS', 'Determine the boundaries and applicability of the QMS and document the scope, including justification for any requirement deemed not applicable.', 'shared', '4.3', 'scope', '["org_profile.standardsInScope","org_profile.sites","applicability.exclusions"]', 30),
  ('d0000001-0001-4000-8000-000000000004', 'ISO9001', '4.4', 'QMS and its processes', 'Establish, implement, maintain and continually improve the QMS and its interacting processes, including inputs, outputs, sequence, criteria and process owners.', 'shared', '4.4', 'procedure', '["org_profile.coreProcesses"]', 40),
  ('d0000001-0001-4000-8000-000000000005', 'ISO9001', '5.1', 'Leadership and commitment', 'Demonstrate top management leadership and commitment to the QMS and ensure customer focus is maintained throughout the organization.', 'shared', '5.1', 'procedure', '["org_profile.managementRep"]', 50),
  ('d0000001-0001-4000-8000-000000000006', 'ISO9001', '5.2', 'Policy', 'Establish a quality policy appropriate to the purpose and context of the organization, communicate it internally, and make it available to interested parties.', 'forked', '5.2', 'policy', '["register.policies"]', 60),
  ('d0000001-0001-4000-8000-000000000007', 'ISO9001', '5.3', 'Organizational roles, responsibilities and authorities', 'Assign, communicate and ensure understanding of the responsibilities and authorities for roles relevant to the QMS.', 'shared', '5.3', 'procedure', '["org_profile.managementRep"]', 70),
  ('d0000001-0001-4000-8000-000000000008', 'ISO9001', '6.1', 'Actions to address risks and opportunities', 'Determine the risks and opportunities that need to be addressed to give assurance that the QMS can achieve its intended results. Plan actions to address them and evaluate the effectiveness of those actions.', 'forked', '6.1', 'procedure', '["register.risks"]', 80),
  ('d0000001-0001-4000-8000-000000000009', 'ISO9001', '6.2', 'Quality objectives and planning to achieve them', 'Establish measurable quality objectives at relevant functions, levels and processes, and plan the actions, resources, responsibilities, timeframes and evaluation of results needed to achieve them.', 'shared', '6.2', 'procedure', '["register.objectives"]', 90),
  ('d0000001-0001-4000-8000-000000000010', 'ISO9001', '6.3', 'Planning of changes', 'Carry out changes to the QMS in a planned manner, considering the purpose of the change, QMS integrity, resource availability, and allocation of responsibilities and authorities.', 'standard_only', '6.3', 'procedure', '["register.change_plans"]', 100),
  ('d0000001-0001-4000-8000-000000000011', 'ISO9001', '7.1', 'Resources', 'Determine and provide the resources needed for the QMS, including people, infrastructure, process environment, monitoring and measuring resources with calibration traceability, and organizational knowledge.', 'shared', '7.1', 'procedure', '["org_profile.employeeCount"]', 110),
  ('d0000001-0001-4000-8000-000000000012', 'ISO9001', '7.2', 'Competence', 'Determine the necessary competence of persons whose work affects quality performance, ensure competence on the basis of education, training or experience, and retain documented evidence.', 'shared', '7.2', 'procedure', '["register.competence"]', 120),
  ('d0000001-0001-4000-8000-000000000013', 'ISO9001', '7.3', 'Awareness', 'Ensure persons doing work under organizational control are aware of the quality policy, relevant quality objectives, their contribution to QMS effectiveness, and the implications of nonconformity.', 'shared', '7.3', 'procedure', '["register.competence"]', 130),
  ('d0000001-0001-4000-8000-000000000014', 'ISO9001', '7.4', 'Communication', 'Determine the internal and external communications relevant to the QMS, including what to communicate, when, with whom, how, and who communicates.', 'shared', '7.4', 'procedure', '["org_profile.coreProcesses"]', 140),
  ('d0000001-0001-4000-8000-000000000015', 'ISO9001', '7.5', 'Documented information', 'Maintain the documented information required by the QMS, ensure appropriate identification, format and approval on creation and update, and control its availability, protection, distribution, retention and disposition.', 'shared', '7.5', 'procedure', '["register.documents"]', 150),
  ('d0000001-0001-4000-8000-000000000016', 'ISO9001', '8.1', 'Operational planning and control', 'Plan, implement and control the processes needed to meet the requirements for the provision of products and services, including criteria, resources, documented information, and control of planned changes and outsourced processes.', 'forked', '8.1', 'procedure', '["org_profile.coreProcesses"]', 160),
  ('d0000001-0001-4000-8000-000000000017', 'ISO9001', '8.2', 'Requirements for products and services', 'Communicate with customers, determine the requirements for products and services including statutory and regulatory ones, review the ability to meet them before commitment, and control changes to requirements.', 'standard_only', '8.2-9001', 'procedure', '["org_profile.productsServices"]', 170),
  ('d0000001-0001-4000-8000-000000000018', 'ISO9001', '8.3', 'Design and development', 'Establish a design and development process with planned stages and controls, defined inputs, reviews, verification and validation, outputs traced to inputs, and controlled design changes.', 'standard_only', '8.3', 'procedure', '["org_profile.designResponsibility"]', 180),
  ('d0000001-0001-4000-8000-000000000019', 'ISO9001', '8.4', 'Control of externally provided processes, products and services', 'Ensure externally provided processes, products and services conform to requirements. Apply criteria for the evaluation, selection, monitoring and re-evaluation of external providers, define the type and extent of control, and communicate requirements to providers.', 'standard_only', '8.4', 'procedure', '["register.suppliers"]', 190),
  ('d0000001-0001-4000-8000-000000000020', 'ISO9001', '8.5', 'Production and service provision', 'Implement production and service provision under controlled conditions, including identification and traceability, care for customer and external-provider property, preservation, post-delivery activities, and control of changes.', 'standard_only', '8.5', 'procedure', '["org_profile.coreProcesses"]', 200),
  ('d0000001-0001-4000-8000-000000000021', 'ISO9001', '8.6', 'Release of products and services', 'Verify that product and service requirements have been met before release, and retain evidence of conformity with traceability to the person authorizing release.', 'standard_only', '8.6', 'procedure', '["org_profile.productsServices"]', 210),
  ('d0000001-0001-4000-8000-000000000022', 'ISO9001', '8.7', 'Control of nonconforming outputs', 'Identify and control nonconforming outputs to prevent unintended use or delivery, take appropriate correction or disposition action, and retain records of nonconformities and actions taken.', 'standard_only', '8.7', 'procedure', '["register.nonconformities"]', 220),
  ('d0000001-0001-4000-8000-000000000023', 'ISO9001', '9.1', 'Monitoring, measurement, analysis and evaluation', 'Determine what needs monitoring and measurement and the methods and timing for monitoring, analysis and evaluation of QMS performance. Monitor customer satisfaction and analyse data on conformity, satisfaction and supplier performance.', 'forked', '9.1', 'procedure', '["register.objectives"]', 230),
  ('d0000001-0001-4000-8000-000000000024', 'ISO9001', '9.2', 'Internal audit', 'Conduct internal audits at planned intervals to determine whether the QMS conforms to requirements and is effectively implemented and maintained, and retain audit records.', 'shared', '9.2', 'procedure', '["register.audits"]', 240),
  ('d0000001-0001-4000-8000-000000000025', 'ISO9001', '9.3', 'Management review', 'Review the QMS at planned intervals at top management level, covering defined inputs and producing decisions and actions as outputs.', 'shared', '9.3', 'procedure', '["register.management_reviews"]', 250),
  ('d0000001-0001-4000-8000-000000000026', 'ISO9001', '10.1', 'General', 'Determine and select opportunities for improvement and implement actions needed to meet customer requirements and enhance customer satisfaction.', 'shared', '10.1', 'procedure', '["register.nonconformities"]', 260),
  ('d0000001-0001-4000-8000-000000000027', 'ISO9001', '10.2', 'Nonconformity and corrective action', 'React to nonconformities, evaluate the need for action to eliminate root causes, implement corrective actions, review their effectiveness, and retain records of nonconformities and actions.', 'forked', '10.2', 'procedure', '["register.nonconformities"]', 270),
  ('d0000001-0001-4000-8000-000000000028', 'ISO9001', '10.3', 'Continual improvement', 'Continually improve the suitability, adequacy and effectiveness of the QMS, using analysis results and management review outputs.', 'shared', '10.3', 'procedure', '["register.nonconformities","register.objectives"]', 280)
INSERT INTO qms.clause_registry (id, standard, clause_no, clause_title, intent_paraphrase, annex_sl_mode, harmonization_key, doc_type, required_sources, sort_order) VALUES
  ('d0000001-0002-4000-8000-000000000001', 'ISO14001', '4.1', 'Understanding the organization and its context', 'Determine the internal and external issues relevant to the EMS, including environmental conditions capable of affecting or being affected by the organization.', 'shared', '4.1', 'procedure', '["org_profile.industry","org_profile.productsServices","register.interested_parties"]', 10),
  ('d0000001-0002-4000-8000-000000000002', 'ISO14001', '4.2', 'Understanding the needs and expectations of interested parties', 'Determine the interested parties relevant to the EMS, their needs and expectations, and which of those needs and expectations become compliance obligations.', 'shared', '4.2', 'procedure', '["register.interested_parties"]', 20),
  ('d0000001-0002-4000-8000-000000000003', 'ISO14001', '4.3', 'Determining the scope of the EMS', 'Determine the boundaries and applicability of the EMS considering context issues, compliance obligations, organizational units, activities, products, services and authority, and document the scope.', 'shared', '4.3', 'scope', '["org_profile.standardsInScope","org_profile.sites","applicability.exclusions"]', 30),
  ('d0000001-0002-4000-8000-000000000004', 'ISO14001', '4.4', 'Environmental management system', 'Establish, implement, maintain and continually improve the EMS and its processes to achieve the intended environmental outcomes.', 'shared', '4.4', 'procedure', '["org_profile.coreProcesses"]', 40),
  ('d0000001-0002-4000-8000-000000000005', 'ISO14001', '5.1', 'Leadership and commitment', 'Demonstrate top management leadership and commitment to the EMS, taking accountability for its effectiveness and ensuring resources are available.', 'shared', '5.1', 'procedure', '["org_profile.managementRep"]', 50),
  ('d0000001-0002-4000-8000-000000000006', 'ISO14001', '5.2', 'Environmental policy', 'Establish an environmental policy that includes commitments to protection of the environment including prevention of pollution, fulfilment of compliance obligations, and continual improvement, and communicate it.', 'forked', '5.2', 'policy', '["register.policies"]', 60),
  ('d0000001-0002-4000-8000-000000000007', 'ISO14001', '5.3', 'Organizational roles, responsibilities and authorities', 'Assign and communicate the responsibilities and authorities for roles relevant to the EMS.', 'shared', '5.3', 'procedure', '["org_profile.managementRep"]', 70),
  ('d0000001-0002-4000-8000-000000000008', 'ISO14001', '6.1', 'Actions to address risks and opportunities', 'Determine the risks and opportunities that need to be addressed to give assurance that the EMS can achieve its intended outcomes. Plan actions to address them, integrate the actions into EMS processes, and evaluate their effectiveness.', 'forked', '6.1', 'procedure', '["register.risks"]', 80),
  ('d0000001-0002-4000-8000-000000000009', 'ISO14001', '6.1.2', 'Environmental aspects', 'Determine the environmental aspects of activities, products and services and their associated environmental impacts from a lifecycle perspective, and identify significant aspects using defined criteria.', 'standard_only', '6.1.2-aspects', 'procedure', '["register.aspects"]', 90),
  ('d0000001-0002-4000-8000-000000000010', 'ISO14001', '6.1.3', 'Compliance obligations', 'Determine and have access to the compliance obligations related to environmental aspects, and determine how those obligations apply to the organization.', 'shared', '6.1.3', 'procedure', '["register.legal_obligations"]', 100),
  ('d0000001-0002-4000-8000-000000000011', 'ISO14001', '6.2', 'Environmental objectives and planning to achieve them', 'Establish environmental objectives at relevant functions and levels consistent with the environmental policy, and plan the actions, resources, responsibilities, timeframes and evaluation indicators to achieve them.', 'shared', '6.2', 'procedure', '["register.objectives"]', 110),
  ('d0000001-0002-4000-8000-000000000012', 'ISO14001', '7.1', 'Resources', 'Determine and provide the resources needed for the establishment, implementation, maintenance and continual improvement of the EMS.', 'shared', '7.1', 'procedure', '["org_profile.employeeCount"]', 120),
  ('d0000001-0002-4000-8000-000000000013', 'ISO14001', '7.2', 'Competence', 'Determine and ensure the competence of persons whose work affects environmental performance or the ability to fulfil compliance obligations, and retain documented evidence.', 'shared', '7.2', 'procedure', '["register.competence"]', 130),
  ('d0000001-0002-4000-8000-000000000014', 'ISO14001', '7.3', 'Awareness', 'Ensure persons doing work under organizational control are aware of the environmental policy, the significant environmental aspects relevant to their work, their contribution, and the implications of not conforming.', 'shared', '7.3', 'procedure', '["register.competence"]', 140),
  ('d0000001-0002-4000-8000-000000000015', 'ISO14001', '7.4', 'Communication', 'Establish processes for internal and external communications relevant to the EMS, including external communication as required by compliance obligations.', 'shared', '7.4', 'procedure', '["org_profile.coreProcesses"]', 150),
  ('d0000001-0002-4000-8000-000000000016', 'ISO14001', '7.5', 'Documented information', 'Maintain the documented information required by the EMS, control its creation and update, and control its availability, protection, distribution, retention and disposition.', 'shared', '7.5', 'procedure', '["register.documents"]', 160),
  ('d0000001-0002-4000-8000-000000000017', 'ISO14001', '8.1', 'Operational planning and control', 'Establish, implement and control the processes needed to meet EMS requirements, applying a lifecycle perspective and operational controls for significant environmental aspects. Control planned changes and ensure outsourced processes are controlled or influenced.', 'forked', '8.1', 'procedure', '["org_profile.coreProcesses"]', 170),
  ('d0000001-0002-4000-8000-000000000018', 'ISO14001', '8.2', 'Emergency preparedness and response', 'Establish, implement and maintain processes to prepare for and respond to potential environmental emergency situations, including periodic testing and review of planned response actions.', 'shared', '8.2-emergency', 'procedure', '["register.emergency_preparedness"]', 180),
  ('d0000001-0002-4000-8000-000000000019', 'ISO14001', '9.1', 'Monitoring, measurement, analysis and evaluation', 'Monitor, measure, analyse and evaluate environmental performance using calibrated or verified equipment. Evaluate fulfilment of compliance obligations and maintain knowledge and understanding of compliance status.', 'forked', '9.1', 'procedure', '["register.objectives"]', 190),
  ('d0000001-0002-4000-8000-000000000020', 'ISO14001', '9.2', 'Internal audit', 'Conduct internal audits at planned intervals under a planned audit programme to determine whether the EMS conforms to requirements and is effectively implemented and maintained.', 'shared', '9.2', 'procedure', '["register.audits"]', 200),
  ('d0000001-0002-4000-8000-000000000021', 'ISO14001', '9.3', 'Management review', 'Review the EMS at planned intervals at top management level, covering defined inputs including compliance evaluation results and environmental performance, and producing decisions and actions as outputs.', 'shared', '9.3', 'procedure', '["register.management_reviews"]', 210),
  ('d0000001-0002-4000-8000-000000000022', 'ISO14001', '10.1', 'General', 'Determine opportunities for improvement and implement the actions needed to achieve the intended outcomes of the EMS.', 'shared', '10.1', 'procedure', '["register.nonconformities"]', 220),
  ('d0000001-0002-4000-8000-000000000023', 'ISO14001', '10.2', 'Nonconformity and corrective action', 'React to nonconformities, evaluate the need for action to eliminate root causes, implement corrective actions, review their effectiveness, and retain records of nonconformities and actions.', 'forked', '10.2', 'procedure', '["register.nonconformities"]', 230),
  ('d0000001-0002-4000-8000-000000000024', 'ISO14001', '10.3', 'Continual improvement', 'Continually improve the suitability, adequacy and effectiveness of the EMS to enhance environmental performance.', 'shared', '10.3', 'procedure', '["register.nonconformities","register.objectives"]', 240)
INSERT INTO qms.clause_registry (id, standard, clause_no, clause_title, intent_paraphrase, annex_sl_mode, harmonization_key, doc_type, required_sources, sort_order) VALUES
  ('d0000001-0003-4000-8000-000000000001', 'ISO45001', '4.1', 'Understanding the organization and its context', 'Determine the external and internal issues relevant to the purpose of the organization that affect its ability to achieve the intended outcomes of the OH&S management system.', 'shared', '4.1', 'procedure', '["org_profile.industry","org_profile.productsServices","register.interested_parties"]', 10),
  ('d0000001-0003-4000-8000-000000000002', 'ISO45001', '4.2', 'Understanding the needs and expectations of workers and other interested parties', 'Determine the workers and other interested parties relevant to the OH&S management system, their needs and expectations, and which of those become legal requirements and other requirements.', 'shared', '4.2', 'procedure', '["register.interested_parties"]', 20),
  ('d0000001-0003-4000-8000-000000000003', 'ISO45001', '4.3', 'Determining the scope of the OH&S management system', 'Determine the boundaries and applicability of the OH&S management system, considering context issues, requirements and planned or performed work-related activities, and document the scope.', 'shared', '4.3', 'scope', '["org_profile.standardsInScope","org_profile.sites","applicability.exclusions"]', 30),
  ('d0000001-0003-4000-8000-000000000004', 'ISO45001', '4.4', 'OH&S management system', 'Establish, implement, maintain and continually improve the OH&S management system and its processes.', 'shared', '4.4', 'procedure', '["org_profile.coreProcesses"]', 40),
  ('d0000001-0003-4000-8000-000000000005', 'ISO45001', '5.1', 'Leadership and commitment', 'Demonstrate top management leadership and commitment, taking overall responsibility and accountability for the prevention of work-related injury and ill health and the protection of workers.', 'shared', '5.1', 'procedure', '["org_profile.managementRep"]', 50),
  ('d0000001-0003-4000-8000-000000000006', 'ISO45001', '5.2', 'OH&S policy', 'Establish an OH&S policy that includes commitments to safe and healthy working conditions, elimination of hazards and reduction of OH&S risks, fulfilment of legal requirements and other requirements, and consultation and participation of workers.', 'forked', '5.2', 'policy', '["register.policies"]', 60),
  ('d0000001-0003-4000-8000-000000000007', 'ISO45001', '5.3', 'Organizational roles, responsibilities and authorities', 'Assign and communicate the responsibilities and authorities for roles relevant to the OH&S management system at all levels of the organization.', 'shared', '5.3', 'procedure', '["org_profile.managementRep"]', 70),
  ('d0000001-0003-4000-8000-000000000008', 'ISO45001', '5.4', 'Consultation and participation of workers', 'Establish processes for the consultation and participation of workers and their representatives at all levels and functions in developing, planning, implementing, evaluating and improving the OH&S management system, removing barriers to participation.', 'standard_only', '5.4', 'procedure', '["register.worker_consultation"]', 80),
  ('d0000001-0003-4000-8000-000000000009', 'ISO45001', '6.1', 'Actions to address risks and opportunities', 'Determine the risks and opportunities that need to be addressed to give assurance that the OH&S management system can achieve its intended outcomes. Plan actions to address them, integrate the actions into system processes, and evaluate their effectiveness.', 'forked', '6.1', 'procedure', '["register.risks"]', 90),
  ('d0000001-0003-4000-8000-000000000010', 'ISO45001', '6.1.2', 'Hazard identification and assessment of risks and opportunities', 'Establish ongoing and proactive processes for hazard identification, and assess the OH&S risks and OH&S opportunities arising from identified hazards using defined methodologies and criteria.', 'standard_only', '6.1.2-hazards', 'procedure', '["register.hazards"]', 100),
  ('d0000001-0003-4000-8000-000000000011', 'ISO45001', '6.1.3', 'Determination of legal requirements and other requirements', 'Determine and have access to the legal requirements and other requirements applicable to hazards and OH&S risks, and determine how those requirements apply to the organization.', 'shared', '6.1.3', 'procedure', '["register.legal_obligations"]', 110),
  ('d0000001-0003-4000-8000-000000000012', 'ISO45001', '6.2', 'OH&S objectives and planning to achieve them', 'Establish OH&S objectives at relevant functions and levels consistent with the OH&S policy, and plan the actions, resources, responsibilities, timeframes and evaluation indicators to achieve them.', 'shared', '6.2', 'procedure', '["register.objectives"]', 120),
  ('d0000001-0003-4000-8000-000000000013', 'ISO45001', '7.1', 'Resources', 'Determine and provide the resources needed for the establishment, implementation, maintenance and continual improvement of the OH&S management system.', 'shared', '7.1', 'procedure', '["org_profile.employeeCount"]', 130),
  ('d0000001-0003-4000-8000-000000000014', 'ISO45001', '7.2', 'Competence', 'Ensure workers are competent on the basis of education, training or experience, including the ability to identify hazards, and retain documented evidence of competence.', 'shared', '7.2', 'procedure', '["register.competence"]', 140),
  ('d0000001-0003-4000-8000-000000000015', 'ISO45001', '7.3', 'Awareness', 'Make workers aware of the OH&S policy, the hazards and OH&S risks relevant to them, incidents relevant to their work, and their ability to remove themselves from work situations presenting imminent and serious danger.', 'shared', '7.3', 'procedure', '["register.competence"]', 150),
  ('d0000001-0003-4000-8000-000000000016', 'ISO45001', '7.4', 'Communication', 'Establish processes for internal and external communications relevant to the OH&S management system, including communication with workers at all levels.', 'shared', '7.4', 'procedure', '["org_profile.coreProcesses"]', 160),
  ('d0000001-0003-4000-8000-000000000017', 'ISO45001', '7.5', 'Documented information', 'Maintain the documented information required by the OH&S management system, control its creation and update, and control its availability, protection, distribution, retention and disposition.', 'shared', '7.5', 'procedure', '["register.documents"]', 170),
  ('d0000001-0003-4000-8000-000000000018', 'ISO45001', '8.1', 'Operational planning and control', 'Plan, implement and control the processes needed to meet OH&S management system requirements and to implement planned actions, establishing operating criteria and maintaining documented information.', 'forked', '8.1', 'procedure', '["org_profile.coreProcesses"]', 180),
  ('d0000001-0003-4000-8000-000000000019', 'ISO45001', '8.1.2', 'Eliminating hazards and reducing OH&S risks', 'Establish processes to eliminate hazards and reduce OH&S risks using the hierarchy of controls: elimination, substitution, engineering controls and reorganization of work, administrative controls including training, and personal protective equipment.', 'standard_only', '8.1.2', 'procedure', '["register.hazards"]', 190),
  ('d0000001-0003-4000-8000-000000000020', 'ISO45001', '8.1.3', 'Management of change', 'Establish processes to implement and control planned changes that affect OH&S performance, with hazard impact assessment before implementation.', 'standard_only', '8.1.3', 'procedure', '["register.change_plans"]', 200),
  ('d0000001-0003-4000-8000-000000000021', 'ISO45001', '8.1.4', 'Procurement', 'Control the procurement of products and services to ensure conformity to OH&S management system requirements, coordinate with contractors on hazards, and ensure outsourced functions and processes are controlled.', 'standard_only', '8.1.4', 'procedure', '["register.suppliers"]', 210),
  ('d0000001-0003-4000-8000-000000000022', 'ISO45001', '8.2', 'Emergency preparedness and response', 'Establish, implement and maintain processes to prepare for and respond to potential emergency situations, addressing the needs of workers, contractors and other interested parties, with periodic testing and review of planned responses.', 'shared', '8.2-emergency', 'procedure', '["register.emergency_preparedness"]', 220),
  ('d0000001-0003-4000-8000-000000000023', 'ISO45001', '9.1', 'Monitoring, measurement, analysis and performance evaluation', 'Monitor, measure, analyse and evaluate OH&S performance using leading and lagging indicators and calibrated or verified equipment. Evaluate fulfilment of legal requirements and other requirements and maintain knowledge of compliance status.', 'forked', '9.1', 'procedure', '["register.objectives"]', 230),
  ('d0000001-0003-4000-8000-000000000024', 'ISO45001', '9.2', 'Internal audit', 'Conduct internal audits at planned intervals under a planned audit programme to determine whether the OH&S management system conforms to requirements and is effectively implemented and maintained.', 'shared', '9.2', 'procedure', '["register.audits"]', 240),
  ('d0000001-0003-4000-8000-000000000025', 'ISO45001', '9.3', 'Management review', 'Review the OH&S management system at planned intervals at top management level, covering defined inputs including incident trends and worker consultation results, and producing decisions and actions as outputs.', 'shared', '9.3', 'procedure', '["register.management_reviews"]', 250),
  ('d0000001-0003-4000-8000-000000000026', 'ISO45001', '10.1', 'General', 'Determine opportunities for improvement and implement the actions needed to achieve the intended outcomes of the OH&S management system.', 'shared', '10.1', 'procedure', '["register.nonconformities"]', 260),
  ('d0000001-0003-4000-8000-000000000027', 'ISO45001', '10.2', 'Incident, nonconformity and corrective action', 'React to incidents and nonconformities, investigate incidents with the participation of workers, evaluate and eliminate root causes, implement corrective actions using the hierarchy of controls, and review their effectiveness with records retained.', 'forked', '10.2', 'procedure', '["register.nonconformities"]', 270),
  ('d0000001-0003-4000-8000-000000000028', 'ISO45001', '10.3', 'Continual improvement', 'Continually improve the suitability, adequacy and effectiveness of the OH&S management system to enhance OH&S performance.', 'shared', '10.3', 'procedure', '["register.nonconformities","register.objectives"]', 280)
